import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './app-shell.css';

import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ValueTable } from '@kerfjs/ui/value-table';
import { delegate, signal } from 'kerfjs';
import { Bell, Folder, Inbox, Menu, Settings } from 'lucide';

const readSize = (key: string, fallback: number) => {
  const value = Number(localStorage.getItem(key));
  return Number.isFinite(value) ? value : fallback;
};

export function createApplicationShell(root: HTMLElement) {
  const selected = signal('inbox');
  const navigationSize = signal(readSize('atlas.navigationSize', 224));
  const inspectorSize = signal(readSize('atlas.inspectorSize', 240));
  const mobileNavOpen = signal(false);

  const render = () => <section class="app-shell kui-layout" data-mobile-nav-open={String(mobileNavOpen.value)}>
    <Toolbar label="Atlas workspace" leading={<><button class="phone-nav" type="button" aria-label="Open navigation" aria-expanded={String(mobileNavOpen.value)} data-action="toggle-navigation"><LucideIcon icon={Menu} name="menu" /></button><ToolbarText text="Atlas" /></>} trailing={<ToolbarControlGroup appearance="borderless" label="Workspace controls"><button type="button" aria-label="Notifications" data-action="notifications"><LucideIcon icon={Bell} name="bell" /></button><button type="button" aria-label="Settings" data-action="settings"><LucideIcon icon={Settings} name="settings" /></button></ToolbarControlGroup>} />
    <div class="app-shell__body">
      <div class="app-shell__nav-region"><ResizableRegion id="atlas-navigation" label="Navigation" size={navigationSize.value} min={180} max={320}><aside class="app-shell__nav kui-sidebar"><MenuHeader label="Workspace" /><nav class="app-shell__nav-scroll kui-scroll-owner" aria-label="Workspace"><MenuItem action="open-section" itemId="inbox" label="Inbox" icon={<LucideIcon icon={Inbox} name="inbox" />} selected={selected.value === 'inbox'} /><MenuItem action="open-section" itemId="projects" label="Projects" icon={<LucideIcon icon={Folder} name="folder" />} selected={selected.value === 'projects'} /></nav></aside></ResizableRegion></div>
      <main class="app-shell__main"><PageHeader title={selected.value === 'inbox' ? 'Inbox triage' : 'Active projects'} action={<button class="app-button" data-primary="true" type="button" data-action="new-task">New task</button>} /><div class="app-shell__workspace-scroll kui-scroll-owner kui-pane-body kui-section-stack"><article class="app-card kui-surface-body"><strong>Release accessibility audit</strong><p>Due this week</p></article><article class="app-card kui-surface-body"><strong>Prepare phone navigation</strong><p>Due next week</p></article></div></main>
      <div class="app-shell__inspector-region"><ResizableRegion id="atlas-inspector" label="Inspector" size={inspectorSize.value} min={200} max={360} edge="start"><aside class="app-shell__inspector"><PageHeader title="Inspector" /><div class="app-shell__inspector-scroll kui-scroll-owner kui-pane-body"><ValueTable label="Selected task"><div><dt>Status</dt><dd>In review</dd></div><div><dt>Owner</dt><dd>Mara Chen</dd></div><div><dt>Priority</dt><dd>High</dd></div></ValueTable></div></aside></ResizableRegion></div>
    </div>
  </section>;

  const disposeActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    const action = element.dataset.action;
    if (action === 'toggle-navigation') mobileNavOpen.value = !mobileNavOpen.value;
    if (action === 'open-section' && element.dataset.itemId) { selected.value = element.dataset.itemId; mobileNavOpen.value = false; }
  });
  const disposeResize = wireResizableRegions(root, (id, size) => {
    if (id === 'atlas-navigation') { navigationSize.value = size; localStorage.setItem('atlas.navigationSize', String(size)); }
    if (id === 'atlas-inspector') { inspectorSize.value = size; localStorage.setItem('atlas.inspectorSize', String(size)); }
  });
  return { render, dispose() { disposeActions(); disposeResize(); } };
}

