.app-shell { display: grid; block-size: 100dvh; min-inline-size: 0; overflow: hidden; grid-template-rows: auto minmax(0, 1fr); background: var(--kui-color-surface); }
.app-shell__body { display: flex; min-inline-size: 0; min-block-size: 0; }
.app-shell__nav, .app-shell__inspector, .app-shell__main { display: grid; min-inline-size: 0; min-block-size: 0; grid-template-rows: auto minmax(0, 1fr); }
.app-shell__main { flex: 1; min-inline-size: 16rem; background: var(--kui-color-surface-lowered); }
.app-shell__nav-scroll, .app-shell__workspace-scroll, .app-shell__inspector-scroll { min-block-size: 0; }
.app-card { border: 1px solid var(--kui-color-border-quiet); border-radius: var(--kui-radius-m); background: var(--kui-color-surface); }
.phone-nav { display: none; }
@media (max-width: 44rem) { .app-shell__inspector-region { display: none; } }
@media (max-width: 28rem) { .phone-nav { display: inline-flex; } .app-shell__nav-region { display: none; } .app-shell[data-mobile-nav-open="true"] .app-shell__nav-region { position: fixed; z-index: 10; inset: auto 0 0 0; display: block; max-block-size: calc(100dvh - 3rem); background: var(--kui-color-surface); } .app-shell__main { min-inline-size: 0; } }
@media (prefers-reduced-motion: reduce) { .app-shell *, .app-shell *::before, .app-shell *::after { scroll-behavior: auto !important; transition-duration: 1ms !important; } }
